// Mock roster - swap for BambooHR/Calendar PTO feed + Metabase volume in production
return [{ json: { engineers: [
  { name: 'Dana', region: 'EU', pto: ['Mon'], lastWeekTickets: 61 },
  { name: 'Marco', region: 'EU', pto: [], lastWeekTickets: 48 },
  { name: 'Lena', region: 'EU', pto: ['Thu', 'Fri'], lastWeekTickets: 44 },
  { name: 'Priya', region: 'US', pto: [], lastWeekTickets: 96 },
  { name: 'Sam', region: 'US', pto: ['Wed'], lastWeekTickets: 31 }
] } }];

const { engineers } = $input.first().json;
const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
const MIN_PER_WINDOW = 2;
let body = 'Next-week coverage plan (Berlin + New York windows):\n\n== Coverage gaps ==\n';
let gaps = 0;
for (const day of days) {
  for (const region of ['EU', 'US']) {
    const avail = engineers.filter(e => e.region === region && !e.pto.includes(day));
    if (avail.length < MIN_PER_WINDOW) {
      gaps++;
      const helpers = engineers.filter(e => e.region !== region && !e.pto.includes(day)).map(e => e.name);
      body += day + ' ' + region + ' window: only ' + avail.map(e => e.name).join('+') + ' available. Ask ' + (helpers[0] || 'nobody') + ' to shift hours or set an async-first day.\n';
    }
  }
}
if (!gaps) body += 'None. All windows have ' + MIN_PER_WINDOW + '+ engineers.\n';
body += '\n== Workload balance (burnout check) ==\n';
const total = engineers.reduce((s, e) => s + e.lastWeekTickets, 0);
for (const e of engineers) {
  const pct = Math.round(100 * e.lastWeekTickets / total);
  body += e.name + ': ' + e.lastWeekTickets + ' tickets (' + pct + '%)' + (pct > 30 ? '  <-- OVER 30%: rebalance assignment rules + check in at 1:1' : '') + '\n';
}
body += '\nPrinciple: coverage is designed, not hoped for; burnout is caught in the data before it is felt.';
return [{ json: { subject: 'Next-week coverage plan: ' + gaps + ' gap(s) to solve', body } }];
